; photo_test.asm - generated by make_photo_test.py: sixteen pages (Light, BIOS Timing, Shapes, Rate); joystick / buttons 1 and 4.

Wait_Recal      equ $F192
Read_Btns       equ $F1BA
Intensity_a     equ $F2AB
Moveto_d        equ $F312
Reset0Ref       equ $F354
Print_Str_d     equ $F37A
Draw_Line_d     equ $F3DF
Draw_VLc        equ $F3CE
Draw_VLp        equ $F410
Vec_Btn_State   equ $C80F
Vec_Text_HW     equ $C82A
Vec_Rfrsh       equ $C83D
Page            equ $C880
Joy_Digital     equ $F1F8
Vec_Joy_1_X     equ $C81B
Vec_Joy_Mux     equ $C81F
Vec_Button_1_1  equ $C812
Vec_Button_1_4  equ $C815
JoyLast         equ $C882

        org     $0000
        fcc     "g GCE 2026"
        fcb     $80
        fdb     $FD0D
        fcb     $F8,$50,$20,-$40
        fcc     "PHOTO TEST"
        fcb     $80
        fcb     0

Start:  clr     Page
        clr     JoyLast
Main:   lda     Page
        asla
        ldx     #RateTab
        ldd     a,x
        std     Vec_Rfrsh          ; the frame timer of this page
        jsr     Wait_Recal
        lda     #$D0
        tfr     a,dp
        setdp   $D0
        jsr     Read_Btns
        ldd     #$0100
        std     Vec_Joy_Mux         ; joystick 1: X only
        clr     Vec_Joy_Mux+2
        clr     Vec_Joy_Mux+3
        jsr     Joy_Digital
        lda     Vec_Joy_1_X
        cmpa    JoyLast
        beq     NoJoy
        sta     JoyLast
        tsta
        beq     NoJoy
        bmi     Prev
        bra     Next
NoJoy:  lda     Vec_Button_1_4
        bne     Next
        lda     Vec_Button_1_1
        bne     Prev
        bra     Go
Next:   lda     Page
        inca
        cmpa    #16
        blo     SetP
        clra
        bra     SetP
Prev:   lda     Page
        deca
        bpl     SetP
        lda     #15
SetP:   sta     Page
Go:     ldb     Page
        aslb
        ldx     #PageTab
        jmp     [b,x]

